CREATE TABLE songs (id TEXT PRIMARY KEY, title TEXT, artist TEXT, album TEXT, release_year INTEGER, duration_ms INTEGER, mbid_recording TEXT, isrc TEXT, identity_state TEXT NOT NULL CHECK (identity_state IN ('matched','needs_review','unmatched','manual')), notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX songs_mbid ON songs(mbid_recording) WHERE mbid_recording IS NOT NULL;
CREATE INDEX songs_isrc ON songs(isrc);
CREATE TABLE song_tags (song_id TEXT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('genre','mood','tag')), value TEXT NOT NULL, source TEXT NOT NULL, weight REAL, PRIMARY KEY (song_id, kind, value, source));
CREATE INDEX song_tags_lookup ON song_tags(kind, value);
CREATE TABLE attribute_values (id TEXT PRIMARY KEY, song_id TEXT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, attribute TEXT NOT NULL CHECK (attribute IN ('bpm','energy','valence','danceability','acousticness','instrumentalness','key','mode')), value_num REAL, value_text TEXT, source TEXT NOT NULL, confidence REAL CHECK (confidence BETWEEN 0 AND 1), fetched_at TEXT NOT NULL, CHECK ((attribute IN ('key','mode') AND value_text IS NOT NULL AND value_num IS NULL) OR (attribute NOT IN ('key','mode') AND value_num IS NOT NULL AND value_text IS NULL)), UNIQUE (song_id, attribute, source));
CREATE TABLE song_links (id TEXT PRIMARY KEY, song_id TEXT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, provider TEXT NOT NULL, external_id TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0, match_state TEXT NOT NULL CHECK (match_state IN ('confirmed','candidate','rejected')), match_score REAL, embeddable INTEGER, created_at TEXT NOT NULL, UNIQUE (provider, external_id, song_id));
CREATE UNIQUE INDEX song_links_one_primary ON song_links(song_id, provider) WHERE is_primary = 1;
CREATE TABLE provider_records (id TEXT PRIMARY KEY, provider TEXT NOT NULL, kind TEXT NOT NULL, external_id TEXT NOT NULL, payload_json TEXT, fetched_at TEXT NOT NULL, expires_at TEXT, UNIQUE (provider, kind, external_id));
CREATE TABLE decks (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, visibility TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','link','public')), source_provider TEXT, source_playlist_id TEXT, imported_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE deck_entries (id TEXT PRIMARY KEY, deck_id TEXT NOT NULL REFERENCES decks(id) ON DELETE CASCADE, song_id TEXT NOT NULL REFERENCES songs(id), position INTEGER NOT NULL, notes TEXT, source_item_id TEXT, source_video_id TEXT, added_at TEXT NOT NULL);
CREATE INDEX deck_entries_pos ON deck_entries(deck_id, position);
CREATE TABLE import_jobs (id TEXT PRIMARY KEY, provider TEXT NOT NULL, source_ref TEXT NOT NULL, deck_id TEXT REFERENCES decks(id), status TEXT NOT NULL CHECK (status IN ('running','done','failed','cancelled')), total INTEGER, matched INTEGER, needs_review INTEGER, unavailable INTEGER, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE import_items (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES import_jobs(id) ON DELETE CASCADE, position INTEGER NOT NULL, video_id TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('pending','matched','needs_review','unmatched','unavailable','resolved')), parsed_artist TEXT, parsed_title TEXT, candidates_json TEXT, chosen_song_id TEXT REFERENCES songs(id));
CREATE INDEX import_items_job_pos ON import_items(job_id, position);
CREATE TABLE matches (id TEXT PRIMARY KEY, ruleset_id TEXT NOT NULL, ruleset_version TEXT NOT NULL, seed INTEGER NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','ended','abandoned')), created_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE match_events (id TEXT PRIMARY KEY, match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE, seq INTEGER NOT NULL, type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (match_id, seq));
CREATE INDEX match_events_match_seq ON match_events(match_id, seq);
CREATE TABLE quota_usage (day_pt TEXT PRIMARY KEY, units INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE VIRTUAL TABLE songs_fts USING fts5(title, artist, album, tags, tokenize = 'unicode61 remove_diacritics 2');